import java.util.*;

public class HashTableBasics {

    // ====== 1. 手写简单哈希表（链地址法） ======
    static class SimpleHashMap {
        private static class Entry {
            int key, value;
            Entry next;
            Entry(int k, int v, Entry n) { key = k; value = v; next = n; }
        }
        private Entry[] table;
        private int size, capacity;

        SimpleHashMap(int cap) {
            capacity = cap;
            table = new Entry[cap];
        }
        private int hash(int key) {
            return Integer.hashCode(key) & (capacity - 1); // 位运算取模
        }
        void put(int key, int value) {
            int i = hash(key);
            for (Entry e = table[i]; e != null; e = e.next) {
                if (e.key == key) { e.value = value; return; } // 更新
            }
            table[i] = new Entry(key, value, table[i]); // 头插
            size++;
        }
        int get(int key) {
            for (Entry e = table[hash(key)]; e != null; e = e.next) {
                if (e.key == key) return e.value;
            }
            return -1; // 未找到
        }
        void remove(int key) {
            int i = hash(key);
            Entry prev = null;
            for (Entry e = table[i]; e != null; prev = e, e = e.next) {
                if (e.key == key) {
                    if (prev == null) table[i] = e.next;
                    else prev.next = e.next;
                    size--;
                    return;
                }
            }
        }
    }

    // ====== 2. 两数之和（哈希表经典应用） ======
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (map.containsKey(complement)) {
                return new int[]{map.get(complement), i};
            }
            map.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }

    // ====== 3. 字符频率统计（HashMap 基本用法） ======
    public Map<Character, Integer> charFrequency(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) {
            freq.merge(c, 1, Integer::sum); // 等价于 getOrDefault + put
        }
        return freq;
    }

    // ====== 4. 字母异位词判断（数组做哈希，仅限小写字母） ======
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
            count[t.charAt(i) - 'a']--;
        }
        for (int c : count) {
            if (c != 0) return false;
        }
        return true;
    }

    // ====== 5. LRU 缓存（LinkedHashMap 的 accessOrder 能力） ======
    static class LRUCache extends LinkedHashMap<Integer, Integer> {
        private final int capacity;
        LRUCache(int capacity) {
            super(capacity, 0.75f, true); // accessOrder = true
            this.capacity = capacity;
        }
        @Override
        public Integer getOrDefault(Object key, Integer def) {
            return super.getOrDefault(key, def);
        }
        @Override
        protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
            return size() > capacity;
        }
    }
}
